import{_ as a}from"./chunks/setup.CfnzVYvt.js";import{_ as e,o,c as r,a2 as s}from"./chunks/framework.DSc8fo6x.js";const m=JSON.parse('{"title":"Installation and first launch","description":"","frontmatter":{},"headers":[],"relativePath":"en/qurasdirma.md","filePath":"en/qurasdirma.md"}'),n={name:"en/qurasdirma.md"};function i(l,t,d,h,c,u){return o(),r("div",null,[...t[0]||(t[0]=[s('<h1 id="installation-and-first-launch" tabindex="-1">Installation and first launch <a class="header-anchor" href="#installation-and-first-launch" aria-label="Permalink to &quot;Installation and first launch&quot;">​</a></h1><p>This page is for the person who installs the program (usually the shop owner). It is done once.</p><h2 id="_1-download-the-program" tabindex="-1">1. Download the program <a class="header-anchor" href="#_1-download-the-program" aria-label="Permalink to &quot;1. Download the program&quot;">​</a></h2><p>Latest version: <strong><a href="https://github.com/Camalzadeh/kassa-releases/releases/latest" target="_blank" rel="noreferrer">Kassa-Setup — download</a></strong> (the <code>Kassa-Setup-….exe</code> file).</p><h2 id="_2-install" tabindex="-1">2. Install <a class="header-anchor" href="#_2-install" aria-label="Permalink to &quot;2. Install&quot;">​</a></h2><ol><li>Open the <code>Kassa-Setup-….exe</code> file.</li><li>If Windows says &quot;unrecognized app&quot;: <strong>&quot;More info&quot; → &quot;Run anyway&quot;</strong>.</li><li>Choose the language (Azərbaycanca, Русский, English).</li><li>Choose the installation mode: <ul><li><strong>&quot;Install for all users&quot; (recommended for a shop)</strong> — Windows asks for the administrator password. The program runs in protected mode: the cashier cannot remove the program or the data. See <a href="#windows">Windows accounts</a>.</li><li><strong>&quot;Install for me only&quot;</strong> — no administrator password needed. For trying it out or a home computer.</li></ul></li><li><strong>Next → Install → Finish</strong>. A green <strong>Kassa</strong> icon appears on the desktop.</li></ol><h2 id="_3-first-launch" tabindex="-1">3. First launch <a class="header-anchor" href="#_3-first-launch" aria-label="Permalink to &quot;3. First launch&quot;">​</a></h2><p><img src="'+a+'" alt="First-time setup"></p><ol><li><strong>Installation password</strong> — get it from the person who gave you the program. It is asked only the first time.</li><li>Choose the language, enter the <strong>shop name</strong>, <strong>your name</strong> and <strong>your password</strong> (at least 8 characters, letters and digits). You become the shop&#39;s <strong>admin</strong>.</li><li><strong>Set up</strong>.</li></ol><h2 id="_4-recovery-code-—-write-it-on-paper" tabindex="-1">4. Recovery code — write it on paper <a class="header-anchor" href="#_4-recovery-code-—-write-it-on-paper" aria-label="Permalink to &quot;4. Recovery code — write it on paper&quot;">​</a></h2><p>After setup, a <strong>recovery code</strong> appears on the screen.</p><ul><li><strong>Write it on paper</strong> and keep it at home or in a safe. Do not store it as a file on the computer.</li><li>If the computer breaks or is stolen, the data can be brought back <strong>only with this code</strong>.</li><li>You can see it later too: <strong>Backup → Recovery code</strong> → your password.</li></ul><p>Tick <strong>&quot;I have written down the code…&quot;</strong> → <strong>Continue</strong>.</p><h2 id="windows" tabindex="-1">5. Windows accounts: a separate account for the cashier <a class="header-anchor" href="#windows" aria-label="Permalink to &quot;5. Windows accounts: a separate account for the cashier {#windows}&quot;">​</a></h2><p>The safest setup (when installed &quot;for all users&quot;):</p><ol><li>For the <strong>owner</strong>: a Windows <strong>administrator account with a password</strong> — they install and update Kassa from it.</li><li>For the <strong>cashier</strong>: a <strong>standard</strong> (non-administrator) account: Settings → Accounts → Other users → <strong>Add account</strong> → account type <strong>&quot;Standard User&quot;</strong>.</li><li>Every day the computer is used in the <strong>cashier&#39;s account</strong>. Kassa works there too, but the cashier cannot delete or change the program or the data files.</li><li>Everyone logs in to Kassa with their own <strong>Kassa name and password</strong> (separate from the Windows password).</li></ol><p>In this mode closing the window does not stop the program completely — it keeps running in the background (Telegram report, backup). This is normal.</p><h2 id="_6-what-to-do-next" tabindex="-1">6. What to do next <a class="header-anchor" href="#_6-what-to-do-next" aria-label="Permalink to &quot;6. What to do next&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Step</th><th>Where</th></tr></thead><tbody><tr><td>Shop details (address, phone, tax ID (VÖEN) — shown on the receipt)</td><td><a href="./ayarlar.html">Settings</a></td></tr><tr><td>Cashier account</td><td><a href="./istifadeciler.html">Users</a></td></tr><tr><td>Entering products</td><td><a href="./mallar.html">Products</a>, <a href="./mal-qebulu.html">Receiving goods</a></td></tr><tr><td>Receipt and label printer</td><td><a href="./printerler.html">Printer</a></td></tr><tr><td>Daily report and backup to your phone</td><td><a href="./telegram.html">Telegram</a></td></tr><tr><td>Weekly USB backup</td><td><a href="./backup.html">Backup</a></td></tr></tbody></table>',19)])])}const f=e(n,[["render",i]]);export{m as __pageData,f as default};
